import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;
  const user = localStorage.getItem('username');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[{ name: 'Accueil', path: '/' }, { name: 'Menu', path: '/menu' }, { name: 'À Propos', path: '/about' }, { name: 'Contact', path: '/contact' }].map((link) => (
            <Link key={link.path} to={link.path} className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}>
              {link.name}
              {isActive(link.path) && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition pr-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>

          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black uppercase text-orange-600 italic border-b-2 border-orange-600">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase hover:underline">Quitter</button>
            </div>
          ) : (
            <>
              <Link to="/register" className="text-gray-900 hover:text-orange-600 text-[11px] font-black uppercase tracking-widest transition">S'inscrire</Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">Connexion</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- LAYOUT ---
const PageLayout = ({ children, title, isHome = false }) => (
  <div className="relative min-h-screen">
    <div className={`${isHome ? 'absolute' : 'fixed'} inset-0 z-0 h-[80vh] md:h-screen`}>
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- HOME (Avis Clients) ---
const Home = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [newComment, setNewComment] = useState("");
  const [stars, setStars] = useState(5);
  const user = localStorage.getItem('username');

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/testimonials/')
      .then(res => setTestimonials(res.data))
      .catch(e => console.log("Erreur testimonials:", e));
  }, []);

  const handleAddReview = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem('token');
    if (!token) {
      alert("Connectez-vous d'abord !");
      return;
    }
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/testimonials/', 
        { content: newComment, stars: parseInt(stars) },
        { headers: { 'Authorization': `Bearer ${token}` } }
      );
      setTestimonials([res.data, ...testimonials]); // Zid l-avis l-foq f l-liste
      setNewComment("");
      alert("Merci pour votre avis !");
    } catch (err) {
      alert("Erreur lors de l'envoi.");
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-white">
      {/* Hero Section */}
      <div className="relative h-[90vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="Hero" />
          <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px]"></div>
        </div>
        <div className="relative z-10 text-center px-6">
          <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-600">Délice</span></h1>
          <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
        </div>
      </div>

      {/* --- AVIS CLIENTS SECTION --- */}
      <div className="bg-white py-24 px-6">
        <div className="max-w-7xl mx-auto">
          <div className="text-center mb-16">
            <h2 className="text-4xl font-black text-gray-900 italic uppercase tracking-tighter mb-4">L'avis de nos clients</h2>
            <div className="h-1.5 w-20 bg-orange-600 mx-auto rounded-full"></div>
          </div>

          {/* Formulaire li l-client y-ktéb fih */}
          {user ? (
            <div className="max-w-2xl mx-auto mb-16 bg-gray-50 p-8 rounded-[2rem] border border-gray-100 shadow-sm">
               <h3 className="font-bold mb-4 text-gray-800 italic">Laissez votre avis :</h3>
               <form onSubmit={handleAddReview} className="space-y-4">
                  <textarea 
                    value={newComment} 
                    onChange={(e)=>setNewComment(e.target.value)} 
                    placeholder="Qu'avez-vous pensé de nos plats ?" 
                    className="w-full p-4 border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-600 outline-none transition" 
                    rows="3"
                    required 
                  />
                  <div className="flex justify-between items-center">
                    <div className="flex items-center space-x-2">
                      <span className="text-sm font-bold text-gray-500">Note:</span>
                      <select value={stars} onChange={(e)=>setStars(e.target.value)} className="p-2 border rounded-xl bg-white font-bold text-orange-600">
                        <option value="5">5 Étoiles</option>
                        <option value="4">4 Étoiles</option>
                        <option value="3">3 Étoiles</option>
                        <option value="2">2 Étoiles</option>
                        <option value="1">1 Étoile</option>
                      </select>
                    </div>
                    <button type="submit" className="bg-orange-600 text-white px-8 py-3 rounded-xl font-black uppercase text-[10px] hover:bg-black transition">Publier</button>
                  </div>
               </form>
            </div>
          ) : (
            <div className="text-center mb-12">
              <p className="text-gray-500 italic"><Link to="/login" className="text-orange-600 font-bold underline">Connectez-vous</Link> pour laisser un avis.</p>
            </div>
          )}

          {/* Affichage dyal l-avis */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {testimonials.length > 0 ? (
              testimonials.map((v, i) => (
                <div key={i} className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 text-center hover:shadow-xl transition-all duration-300">
                  <div className="text-orange-500 mb-4 text-xl">{"★".repeat(v.stars)}</div>
                  <p className="text-gray-700 italic font-bold mb-4">"{v.content}"</p>
                  <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest">— {v.user}</span>
                </div>
              ))
            ) : (
              <p className="col-span-3 text-center text-gray-400 italic">Aucun avis pour le moment.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

