// --- MENU ---
const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [activeCategory, setActiveCategory] = useState("Tout");
  const allDishes = categories.flatMap(c => (c.dishes || []).map(dish => ({ ...dish, categoryName: c.name })));
  const filteredDishes = activeCategory === "Tout" ? allDishes : allDishes.filter(item => item.categoryName === activeCategory);

  return (
    <PageLayout title="Menu">
      <div className="flex flex-wrap justify-center gap-3 mb-12">
        <button onClick={() => setActiveCategory("Tout")} className={`px-8 py-3 rounded-full font-black uppercase text-[10px] border ${activeCategory === "Tout" ? "bg-orange-600 text-white" : "text-white/50 border-white/10"}`}>Tout</button>
        {categories.map(cat => (
          <button key={cat.id} onClick={() => setActiveCategory(cat.name)} className={`px-8 py-3 rounded-full font-black uppercase text-[10px] border ${activeCategory === cat.name ? "bg-orange-600 text-white" : "text-white/50 border-white/10"}`}>{cat.name}</button>
        ))}
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredDishes.map(item => (
          <div key={item.id} className="bg-black/40 backdrop-blur-lg border border-white/10 rounded-[3rem] overflow-hidden">
            <div className="h-64"><img src={item.image} alt={item.name} className="w-full h-full object-cover" /></div>
            <div className="p-8 text-center text-white">
              <h3 className="text-2xl font-black italic uppercase">{item.name}</h3>
              <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
              <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px]">Commander</button>
            </div>
          </div>
        ))}
      </div>
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center">
            <h3 className="text-2xl font-black mb-4 uppercase">Mode</h3>
            <button onClick={() => { addToCart({...selectedItem, type: 'Sur Place'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-100 rounded-2xl font-black mb-2">🍽️ Sur Place</button>
            <button onClick={() => { addToCart({...selectedItem, type: 'À Emporter'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black">🛍️ À Emporter</button>
          </div>
        </div>
      )}
    </PageLayout>
  );
};

// --- PANIER ---
const Panier = ({ cart }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 p-12 rounded-[3.5rem] text-white">
      {cart.length === 0 ? <p className="text-center italic opacity-60">Panier vide.</p> : (
        <div className="space-y-4">
          {cart.map((item, i) => (
            <div key={i} className="flex justify-between border-b border-white/10 pb-4">
              <span>{item.name} ({item.type})</span><span>{item.price} DH</span>
            </div>
          ))}
          <div className="pt-6 flex justify-between text-2xl font-black"><span>Total:</span><span className="text-orange-600">{cart.reduce((a, b) => a + parseFloat(b.price), 0)} DH</span></div>
